(384195, 32619, 2752, '<td valign="top">lovely skin tones and I like the draping.  Good composition and use of colors.(9)</td>', 'lovely skin tones and I like the draping.  Good composition and use of colors.(9)', '2003-08-11 11:20:07.000000', NULL, 1),
(384197, 32614, 6624, '<td valign="top">a little more or a little less abstract would work better for me...shot glass monocle effect works as does the dizzying but the red area at the top does not work for me</td>', 'a little more or a little less abstract would work better for me...shot glass monocle effect works as does the dizzying but the red area at the top does not work for me', '2003-08-11 11:20:45.000000', NULL, 1),
(384198, 32847, 7504, '<td valign="top">I think this is the essence of this challenge.  This makes me want to go to the window and see the beautiful view outside.  It leaves me wanting more!</td>', 'I think this is the essence of this challenge.  This makes me want to go to the window and see the beautiful view outside.  It leaves me wanting more!', '2003-08-11 11:21:08.000000', NULL, 1),
