(384202, 32799, 7543, '<td valign="top">Hallgrimskirkja?</td>', 'Hallgrimskirkja?', '2003-08-11 11:22:12.000000', NULL, 1),
(384203, 32890, 5728, '<td valign="top">At first I had to look a little longer to figure out what this was. It is difficult to tell whether the boy is climbing up the side or is on top of that structure, that is what makes this so interesting. The sepia toning really boosts this photo, better than the color version in my opinion. (I wouldn''t mind seeing how this was in color actually).</td>', 'At first I had to look a little longer to figure out what this was. It is difficult to tell whether the boy is climbing up the side or is on top of that structure, that is what makes this so interesting. The sepia toning really boosts this photo, better than the color version in my opinion. (I wouldn''t mind seeing how this was in color actually).', '2003-08-11 11:22:20.000000', NULL, 1),
(384205, 32859, 7504, '<td valign="top">I like this a lot.  It''s nice and moody, and your model is grea!</td>', 'I like this a lot.  It''s nice and moody, and your model is grea!', '2003-08-11 11:22:48.000000', NULL, 1),
(384206, 32619, 6624, '<td valign="top">nice skin tones and the zipper effect is interesting the overall effect is flat for me, however,</td>', 'nice skin tones and the zipper effect is interesting the overall effect is flat for me, however,', '2003-08-11 11:23:35.000000', NULL, 1),
(384207, 32921, 7543, '<td valign="top">Nice to finally see a "soft" pic, not oversharp. Great lighting, window shadow is great. Composition is good.</td>', 'Nice to finally see a "soft" pic, not oversharp. Great lighting, window shadow is great. Composition is good.', '2003-08-11 11:23:50.000000', NULL, 1),
(384208, 32757, 7504, '<td valign="top">Oh how cute is this!  My kids would love one of these little guys, is it what they call a teacup dog?</td>', 'Oh how cute is this!  My kids would love one of these little guys, is it what they call a teacup dog?', '2003-08-11 11:23:51.000000', NULL, 1),
(384210, 32829, 7504, '<td valign="top">Man, I really want to give this a 10 because I love it!  It doesn''t fit the challenge so well in my book though, darn.  I''ll give it a 7 anyway.</td>', 'Man, I really want to give this a 10 because I love it!  It doesn''t fit the challenge so well in my book though, darn.  I''ll give it a 7 anyway.', '2003-08-11 11:25:04.000000', NULL, 1),
(384211, 32864, 6624, '<td valign="top">the eskimo parka effect around the child''s face is nice, it seems more of a memorabilia shot than not however</td>', 'the eskimo parka effect around the child''s face is nice, it seems more of a memorabilia shot than not however', '2003-08-11 11:25:08.000000', NULL, 1),
(384212, 32916, 2752, '<td valign="top">This is a powerful shot..the anticipation on his face is eloquent.  the color works well here . A definite WOW.(10)</td>', 'This is a powerful shot..the anticipation on his face is eloquent.  the color works well here . A definite WOW.(10)', '2003-08-11 11:25:57.000000', NULL, 1),
