(384214, 32570, 6624, '<td valign="top">this certainly meets the challenge and the colors are satisfying, as is the stucco around the window very nice overall but lacks intensity</td>', 'this certainly meets the challenge and the colors are satisfying, as is the stucco around the window very nice overall but lacks intensity', '2003-08-11 11:26:31.000000', NULL, 1),
(384215, 32324, 7504, '<td valign="top">Nicely done.  Woudn''t want to be in there!</td>', 'Nicely done.  Woudn''t want to be in there!', '2003-08-11 11:27:25.000000', NULL, 1),
(384218, 32489, 6624, '<td valign="top">nice balance of color in the reds...smehow this doesn''t quite "come off" for me.  I think judicious cropping top and bottom would have intensified the effect you were reaching for</td>', 'nice balance of color in the reds...smehow this doesn''t quite "come off" for me.  I think judicious cropping top and bottom would have intensified the effect you were reaching for', '2003-08-11 11:28:30.000000', NULL, 1),
