(384222, 32781, 6624, '<td valign="top">I like the textures and angles of this and there''s just enough outside the window (in contrast to the cloistered effect inside) to give it an edge</td>', 'I like the textures and angles of this and there''s just enough outside the window (in contrast to the cloistered effect inside) to give it an edge', '2003-08-11 11:31:48.000000', NULL, 1),
(384223, 32920, 6624, '<td valign="top">this is flat to me...it is an interesting composition in terms of shape but there is no content for my eye to pursue</td>', 'this is flat to me...it is an interesting composition in terms of shape but there is no content for my eye to pursue', '2003-08-11 11:32:51.000000', NULL, 1),
