(384231, 32912, 6624, '<td valign="top">I like the light and shadow and all the textures</td>', 'I like the light and shadow and all the textures', '2003-08-11 11:38:16.000000', NULL, 1),
(384234, 32829, 3102, '<td valign="top">This certainly ought to earn a ribbon -- it''s wonderful! - 10</td>', 'This certainly ought to earn a ribbon -- it''s wonderful! - 10', '2003-08-11 11:39:16.000000', NULL, 1),
(384236, 32908, 6624, '<td valign="top">this is not as clear a reflection of the title as was intended in my view...a crop on the left taking out the unfocused  item would have clarified it a bit</td>', 'this is not as clear a reflection of the title as was intended in my view...a crop on the left taking out the unfocused  item would have clarified it a bit', '2003-08-11 11:39:58.000000', NULL, 1),
