(384243, 32906, 6624, '<td valign="top">interesting perspective indeed -</td>', 'interesting perspective indeed -', '2003-08-11 11:42:47.000000', NULL, 1),
(384273, 32498, 6624, '<td valign="top">interesting response to challenge - I wish the wasp stood out more but the framing is good and I can feel the stickiness</td>', 'interesting response to challenge - I wish the wasp stood out more but the framing is good and I can feel the stickiness', '2003-08-11 12:08:42.000000', NULL, 1),
(384303, 32594, 10414, '<td valign="top">Very interesting picture! Are those lights hanging from the ceiling??  :)</td>', 'Very interesting picture! Are those lights hanging from the ceiling??  :)', '2003-08-11 12:30:05.000000', NULL, 1),
