(384728, 32753, 6008, '<td valign="top">The main problem with this is the major distortion/grain. As the title suggests a distorted view I''m not sure if that was your intention or just the left eye being distorted. It seems to look like a television when you''re 2mm away from the screen.</td>', 'The main problem with this is the major distortion/grain. As the title suggests a distorted view I''m not sure if that was your intention or just the left eye being distorted. It seems to look like a television when you''re 2mm away from the screen.', '2003-08-11 20:50:23.000000', NULL, 1),
(384730, 32277, 6008, '<td valign="top">This isnt too bad. The surrounding vegetation doesnt really make it obvious that he''s inside a lily, but I guess that''s a good thing about titles! It looks like because he was enclosed in the lily that there wasnt much light, hence why it seems a little soft. His green seems a little oversaturated and could have done with a little more contrast, and possibly used curves to work on the light flashes near his eyes and nose.</td>', 'This isnt too bad. The surrounding vegetation doesnt really make it obvious that he''s inside a lily, but I guess that''s a good thing about titles! It looks like because he was enclosed in the lily that there wasnt much light, hence why it seems a little soft. His green seems a little oversaturated and could have done with a little more contrast, and possibly used curves to work on the light flashes near his eyes and nose.', '2003-08-11 20:56:06.000000', NULL, 1),
(384732, 31934, 200, '<td valign="top">Excellent shot! Fits the challenge perfectly....good luck!</td>', 'Excellent shot! Fits the challenge perfectly....good luck!', '2003-08-11 21:00:10.000000', NULL, 1),
(384735, 31941, 6008, '<td valign="top">This is a pretty good dragonfly image, he has quite a wingspan. I''m not really one for saying this, but I dont really see a connection to the challenge topic. It''s very likely he may be inside something, but the shot doesnt show that and so it would be quite a stretch to say it was on topic. Outside of the challenge, other than what appears to be a light flash near his eye, it''s a good catch.</td>', 'This is a pretty good dragonfly image, he has quite a wingspan. I''m not really one for saying this, but I dont really see a connection to the challenge topic. It''s very likely he may be inside something, but the shot doesnt show that and so it would be quite a stretch to say it was on topic. Outside of the challenge, other than what appears to be a light flash near his eye, it''s a good catch.', '2003-08-11 21:00:54.000000', NULL, 1),
(384737, 32906, 200, '<td valign="top">I love this shot...and the title....good luck!</td>', 'I love this shot...and the title....good luck!', '2003-08-11 21:02:04.000000', NULL, 1),
(384739, 32886, 200, '<td valign="top">Beautiful image and interpretation. Good luck in the challenge!</td>', 'Beautiful image and interpretation. Good luck in the challenge!', '2003-08-11 21:03:03.000000', NULL, 1),
(384741, 32858, 6008, '<td valign="top">I''ve seen these glasses before, they are kind of fun. I''m not a fan of abstract, but the ripples of the glass make an interesting texture with the colors. I''m not sure you needed to be so exact with your title, though, something as simple as ''glitter'' would have worked well and helped with the feeling of abstract. I like that the bottom of the glass is not dead center, too.</td>', 'I''ve seen these glasses before, they are kind of fun. I''m not a fan of abstract, but the ripples of the glass make an interesting texture with the colors. I''m not sure you needed to be so exact with your title, though, something as simple as ''glitter'' would have worked well and helped with the feeling of abstract. I like that the bottom of the glass is not dead center, too.', '2003-08-11 21:04:52.000000', NULL, 1),
(384742, 32781, 200, '<td valign="top">Excellent image! what a fine example of light and shadow. The lines, textures and color all blend together in such harmoney and grace. Nice job!</td>', 'Excellent image! what a fine example of light and shadow. The lines, textures and color all blend together in such harmoney and grace. Nice job!', '2003-08-11 21:05:07.000000', NULL, 1),
(384744, 32826, 200, '<td valign="top">beautiful window...wonderful shot!</td>', 'beautiful window...wonderful shot!', '2003-08-11 21:05:54.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(384747, 32890, 200, '<td valign="top">I love the title! ....love the image! Good luck in the challenge :)</td>', 'I love the title! ....love the image! Good luck in the challenge :)', '2003-08-11 21:07:06.000000', NULL, 1),
(384749, 32859, 200, '<td valign="top">great image....nice work!</td>', 'great image....nice work!', '2003-08-11 21:08:27.000000', NULL, 1),
(384750, 32872, 200, '<td valign="top">Now this is clever!....and very well done....good luck :)</td>', 'Now this is clever!....and very well done....good luck :)', '2003-08-11 21:09:29.000000', NULL, 1),
(384751, 32898, 6008, '<td valign="top">The choice of black and white was an interesting one, giving it more of a ''documentary'' type feel than the standard view of a fridge. The look on his face seems to echo the concern in the title, which is good, however, the focus seems to be on the hershey''s syrup and not his face, unfortunately. I''m not sure what the semi-circle is on the bottom of the image but I find it a little distracting. His eyes seem to be drawn to it, so if that is the choice of food I think having the camera behind that and yet focusing past it may have been an interesting choice.</td>', 'The choice of black and white was an interesting one, giving it more of a ''documentary'' type feel than the standard view of a fridge. The look on his face seems to echo the concern in the title, which is good, however, the focus seems to be on the hershey''s syrup and not his face, unfortunately. I''m not sure what the semi-circle is on the bottom of the image but I find it a little distracting. His eyes seem to be drawn to it, so if that is the choice of food I think having the camera behind that and yet focusing past it may have been an interesting choice.', '2003-08-11 21:10:08.000000', NULL, 1),
(384752, 32901, 200, '<td valign="top">What a fun idea....and a beautiful home! Did you place the camera on self timer?...or does the box open from two directions? Nice work :)</td>', 'What a fun idea....and a beautiful home! Did you place the camera on self timer?...or does the box open from two directions? Nice work :)', '2003-08-11 21:10:50.000000', NULL, 1),
(384753, 32614, 6008, '<td valign="top">It''s an interesting image, although I''m not really a fan of abstracts. I can recognise the wine bottle, but the rest is mostly a blur, which is what I suppose abstracts are like. It doesnt really hold much interest for me, but it does meet the challenge.</td>', 'It''s an interesting image, although I''m not really a fan of abstracts. I can recognise the wine bottle, but the rest is mostly a blur, which is what I suppose abstracts are like. It doesnt really hold much interest for me, but it does meet the challenge.', '2003-08-11 21:11:48.000000', NULL, 1),
(384754, 32500, 200, '<td valign="top">I just love the head! great textures and contrast on her face....what a wonderful prop...such haunting images you can create with this. Nice work and good luck :)</td>', 'I just love the head! great textures and contrast on her face....what a wonderful prop...such haunting images you can create with this. Nice work and good luck :)', '2003-08-11 21:12:55.000000', NULL, 1),
(384755, 32497, 6008, '<td valign="top">Framing the shot with the bottles on either side is interesting. Having a (seemingly) large hand coming at the food forces the viewer to see it as if from the angle of being the food, which is a nice addition.. It meets the challenge, and is fine as an image, but I just couldnt see myself hanging something like this on my wall.</td>', 'Framing the shot with the bottles on either side is interesting. Having a (seemingly) large hand coming at the food forces the viewer to see it as if from the angle of being the food, which is a nice addition.. It meets the challenge, and is fine as an image, but I just couldnt see myself hanging something like this on my wall.', '2003-08-11 21:14:21.000000', NULL, 1),
(384756, 32223, 200, '<td valign="top">Cool shot!</td>', 'Cool shot!', '2003-08-11 21:14:23.000000', NULL, 1),
(384758, 32870, 200, '<td valign="top">I love the expression on his face....so deep in thought. Kids are so cool! I love to hear what they really think about and ponder. This photo makes me want to talk to him and hear what fabulous things are floating around in his imagination! Nice work :)</td>', 'I love the expression on his face....so deep in thought. Kids are so cool! I love to hear what they really think about and ponder. This photo makes me want to talk to him and hear what fabulous things are floating around in his imagination! Nice work :)', '2003-08-11 21:16:58.000000', NULL, 1),
(384759, 32620, 6008, '<td valign="top">I went to the zoo this weekend and know very well how difficult it is to take a photograph through glass, especially with all the smudges and dirt that collect on them. I can see what you were trying to achieve, and it''s a good idea. Being through the glass has forced the animals to be a little blurry and out of focus. I''m not sure if the grey blur on the right is someone outside of the tank or another animal, but it is quite distracting. It meets the challenge, but due to the various little things it doesnt quite have that ''wow'' factor.</td>', 'I went to the zoo this weekend and know very well how difficult it is to take a photograph through glass, especially with all the smudges and dirt that collect on them. I can see what you were trying to achieve, and it''s a good idea. Being through the glass has forced the animals to be a little blurry and out of focus. I''m not sure if the grey blur on the right is someone outside of the tank or another animal, but it is quite distracting. It meets the challenge, but due to the various little things it doesnt quite have that ''wow'' factor.', '2003-08-11 21:18:01.000000', NULL, 1),
(384760, 32391, 200, '<td valign="top">Fun! ..nice title too :)</td>', 'Fun! ..nice title too :)', '2003-08-11 21:18:27.000000', NULL, 1),
(384762, 32757, 200, '<td valign="top">awwww....perfect shot!</td>', 'awwww....perfect shot!', '2003-08-11 21:19:01.000000', NULL, 1),
(384763, 32918, 200, '<td valign="top">Cool pic....cool title! nice job!</td>', 'Cool pic....cool title! nice job!', '2003-08-11 21:19:31.000000', NULL, 1),
(384765, 32498, 6008, '<td valign="top">The symmetry of the glass is interesting, and I like that it was just the half and not the full glass in the shot. It certainly meets the challenge. I''m kind of mixed between liking this and not liking it. Part of me sees it as an interesting way to frame a bug shot, the other part sees it as a snapshot of something you see every summer. Perhaps if there was more detail/closer on the bug (as in a smaller container) then it wouldnt be as hard. Then again it doesnt really look like it was a staged shot either.</td>', 'The symmetry of the glass is interesting, and I like that it was just the half and not the full glass in the shot. It certainly meets the challenge. I''m kind of mixed between liking this and not liking it. Part of me sees it as an interesting way to frame a bug shot, the other part sees it as a snapshot of something you see every summer. Perhaps if there was more detail/closer on the bug (as in a smaller container) then it wouldnt be as hard. Then again it doesnt really look like it was a staged shot either.', '2003-08-11 21:30:16.000000', NULL, 1),
(384773, 32905, 6008, '<td valign="top">I''m not sure if this was staged or you stumbled onto it while out and about. It meets the challenge and is certainly cute. A few things I probably would have changed, though - The harsh shadow on the left unbalances it a little, I would have likely cropped it out. Incidentally the border well very well for this. If this was staged then I think I would have seen how it looked in different light. It seems like a pretty bright light with some harsh shadows so I''m guessing this was around the afternoon time. Slightly earlier or later may have helped soften the light more and compliment the children, adding more of a glow than harshness. Otherwise perhaps having them step back a little so that the shadows feel across them may have been interesting too. Just a little something to add ''wow'' and set it apart from ''just another kid pic''</td>', 'I''m not sure if this was staged or you stumbled onto it while out and about. It meets the challenge and is certainly cute. A few things I probably would have changed, though - The harsh shadow on the left unbalances it a little, I would have likely cropped it out. Incidentally the border well very well for this. If this was staged then I think I would have seen how it looked in different light. It seems like a pretty bright light with some harsh shadows so I''m guessing this was around the afternoon time. Slightly earlier or later may have helped soften the light more and compliment the children, adding more of a glow than harshness. Otherwise perhaps having them step back a little so that the shadows feel across them may have been interesting too. Just a little something to add ''wow'' and set it apart from ''just another kid pic''', '2003-08-11 21:36:28.000000', NULL, 1),
(384785, 32691, 6008, '<td valign="top">At first glance this seemed very much like a snapshot. I get the whole mime looking out of his invisible glass wall structure so it met the challenge, but still seemed like a snapshot. Then as I was scrolling down to get a better view my browser cut out the people on the top and just left the mime and the negative space of cobblestone and it had much more of an impact. It still was a candid, but him holding up his hands to the negative space just makes it more curious. I think had you cropped out the top your score would have been much better.</td>', 'At first glance this seemed very much like a snapshot. I get the whole mime looking out of his invisible glass wall structure so it met the challenge, but still seemed like a snapshot. Then as I was scrolling down to get a better view my browser cut out the people on the top and just left the mime and the negative space of cobblestone and it had much more of an impact. It still was a candid, but him holding up his hands to the negative space just makes it more curious. I think had you cropped out the top your score would have been much better.', '2003-08-11 21:41:33.000000', NULL, 1),
(384786, 32796, 200, '<td valign="top">this is cool.....id like to know how you did it...good luck in the challenge!</td>', 'this is cool.....id like to know how you did it...good luck in the challenge!', '2003-08-11 21:42:01.000000', NULL, 1),
(384787, 32619, 200, '<td valign="top">nice job!</td>', 'nice job!', '2003-08-11 21:42:47.000000', NULL, 1),
