(384790, 32489, 200, '<td valign="top">great idea! I love the color in this shot...beautiful exposure.</td>', 'great idea! I love the color in this shot...beautiful exposure.', '2003-08-11 21:46:10.000000', NULL, 1),
(384792, 32799, 200, '<td valign="top">what a grand window! and i bet an amazing view on the other side. Lovely image....nice work</td>', 'what a grand window! and i bet an amazing view on the other side. Lovely image....nice work', '2003-08-11 21:47:33.000000', NULL, 1),
(384793, 32272, 200, '<td valign="top">excellent shot!</td>', 'excellent shot!', '2003-08-11 21:48:35.000000', NULL, 1),
(384799, 32765, 200, '<td valign="top">I think this is a good idea...and Im hoping she is simply a great little actress...I would hate to think someone so young and precious could be as disturbed as she seems. You did a nice job with this shot and your model deserves congrats on her emotive abilities! Good luck in the challenge....nice work :)</td>', 'I think this is a good idea...and Im hoping she is simply a great little actress...I would hate to think someone so young and precious could be as disturbed as she seems. You did a nice job with this shot and your model deserves congrats on her emotive abilities! Good luck in the challenge....nice work :)', '2003-08-11 22:00:59.000000', NULL, 1),
(384800, 32570, 200, '<td valign="top">now that is funny! and maybe not far from the truth?! Good luck in the challenge :)</td>', 'now that is funny! and maybe not far from the truth?! Good luck in the challenge :)', '2003-08-11 22:02:42.000000', NULL, 1),
(384802, 32829, 200, '<td valign="top">This is a truly beautiful shot....very nice work!</td>', 'This is a truly beautiful shot....very nice work!', '2003-08-11 22:03:38.000000', NULL, 1),
