(384879, 32691, 200, '<td valign="top">funny title :)</td>', 'funny title :)', '2003-08-12 00:21:58.000000', NULL, 1),
(384882, 32886, 9679, '<td valign="top">Great shot. Good job on the lighting and good choice going B&amp;W. The clouds, the light shining on the water and the craggy branch hanging down give this lots of drama. 10</td>', 'Great shot. Good job on the lighting and good choice going B&W. The clouds, the light shining on the water and the craggy branch hanging down give this lots of drama. 10', '2003-08-12 00:30:31.000000', NULL, 1),
