(387002, 32757, 10611, '<td valign="top">Cute Shot! did the doggy get out of that thing??</td>', 'Cute Shot! did the doggy get out of that thing??', '2003-08-13 16:48:26.000000', NULL, 1),
(387004, 32902, 6597, '<td valign="top">very good composition   7</td>', 'very good composition   7', '2003-08-13 16:49:04.000000', NULL, 1),
(387005, 32694, 6597, '<td valign="top">very good 8</td>', 'very good 8', '2003-08-13 16:50:27.000000', NULL, 1),
(387012, 32828, 10611, '<td valign="top">this might work even better for MOvies!!</td>', 'this might work even better for MOvies!!', '2003-08-13 16:54:35.000000', NULL, 1),
(387017, 32619, 10611, '<td valign="top">HAHAHAHA, Great idea!</td>', 'HAHAHAHA, Great idea!', '2003-08-13 16:56:15.000000', NULL, 1),
(387127, 32870, 9043, '<td valign="top">very interesting shot. why is he looking out of the window? try it on a rainy day it would then give the shot emotion. i like it.</td>', 'very interesting shot. why is he looking out of the window? try it on a rainy day it would then give the shot emotion. i like it.', '2003-08-13 18:21:07.000000', NULL, 1),
(387423, 32757, 3306, '<td valign="top">Wow, Thats a tiny dog. Cute. 9</td>', 'Wow, Thats a tiny dog. Cute. 9', '2003-08-13 23:14:24.000000', NULL, 1),
(387425, 32716, 3306, '<td valign="top">My favorite picture of the challenge. The Black and White really helps to set the mood. The contrast, Shadows and angle of the picture are perfect. Excellent shot. Good luck. 10</td>', 'My favorite picture of the challenge. The Black and White really helps to set the mood. The contrast, Shadows and angle of the picture are perfect. Excellent shot. Good luck. 10', '2003-08-13 23:16:52.000000', NULL, 1),
(387426, 32796, 3306, '<td valign="top">Interesting, thoughtful picture.</td>', 'Interesting, thoughtful picture.', '2003-08-13 23:17:39.000000', NULL, 1),
